"""``vern init`` scaffolding for vernier.toml and GitHub Actions workflow."""

from __future__ import annotations

from pathlib import Path

VERNIER_TOML = """\
# Vernier local config (scaffolded by `vern init`)
# Network guarantee: vern makes ZERO network requests other than to the
# model provider you have already configured.

[vernier]
corpus_path = "{corpus_path}"
max_severity = "{max_severity}"

# Optional live-diff overrides for CI (also set via Action inputs / env):
# model = "gpt-4o-mini"
# baseline_model = "gpt-4o"
"""

WORKFLOW_YML = """\
# Generated by `vern init` — Vernier CI gate
name: Vernier gate

on:
  pull_request:
  push:
    branches: [main, master]

permissions:
  contents: read
  pull-requests: write
  statuses: write

concurrency:
  group: vernier-gate-${{{{ github.workflow }}}}-${{{{ github.ref }}}}
  cancel-in-progress: true

jobs:
  vernier-gate:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Vernier gate
        id: vern
        uses: {action_ref}
        with:
          corpus-path: {corpus_path}
          max-severity: {max_severity}
          # model: ${{{{ secrets.OPENAI_MODEL }}}}   # optional; uses provider key only
          # fail-on-miss: "true"
        env:
          # Provider key you already use — Vernier adds no other secrets.
          OPENAI_API_KEY: ${{{{ secrets.OPENAI_API_KEY }}}}
"""


def run_init(
    root: Path,
    *,
    force: bool = False,
    action_ref: str = "gautamtalksdev/Vernier@main",
    corpus_path: str = "vernier-corpus",
    max_severity: str = "MEDIUM",
) -> list[str]:
    """Write vernier.toml and .github/workflows/vernier-gate.yml. Return paths."""
    root = root.resolve()
    root.mkdir(parents=True, exist_ok=True)
    written: list[str] = []

    toml_path = root / "vernier.toml"
    if toml_path.exists() and not force:
        raise FileExistsError(f"{toml_path} exists (pass --force to overwrite)")
    toml_path.write_text(
        VERNIER_TOML.format(corpus_path=corpus_path, max_severity=max_severity),
        encoding="utf-8",
        newline="\n",
    )
    written.append(str(toml_path.relative_to(root)))

    wf_dir = root / ".github" / "workflows"
    wf_dir.mkdir(parents=True, exist_ok=True)
    wf_path = wf_dir / "vernier-gate.yml"
    if wf_path.exists() and not force:
        raise FileExistsError(f"{wf_path} exists (pass --force to overwrite)")
    # Escape braces for format: WORKFLOW already uses doubled braces for GHA.
    wf_path.write_text(
        WORKFLOW_YML.format(
            action_ref=action_ref,
            corpus_path=corpus_path,
            max_severity=max_severity,
        ),
        encoding="utf-8",
        newline="\n",
    )
    written.append(str(wf_path.relative_to(root)))
    return written
